INSERT INTO qa_answer_cancel_task (
    answer_id, task_status, attempt_count, next_attempt_at,
    lease_owner, lease_until, last_error_code, created_at, updated_at
) VALUES (
    #{answerId}, 'PENDING', 0, #{nextAttemptAt},
    NULL, NULL, NULL, #{now}, #{now}
)

mapper.update:
UPDATE qa_answer
SET message_id = #{messageId}
WHERE public_id = #{answerId}
  AND status IN ('GENERATING', 'CANCEL_REQUESTED')
  AND (message_id IS NULL OR message_id = #{messageId})

UPDATE qa_answer_cancel_task
SET next_attempt_at = #{dispatchAt},
    updated_at = #{dispatchAt}
WHERE answer_id = #{answerId}
  AND task_status = 'PENDING'

UPDATE qa_answer
SET status = 'CANCEL_FAILED',
    cancel_error_code = #{errorCode},
    completed_at = #{now}
WHERE public_id = #{answerId}
  AND status = 'CANCEL_REQUESTED'
  AND EXISTS (
      SELECT 1
      FROM qa_answer_cancel_task
      WHERE answer_id = #{answerId}
        AND task_status = 'PROCESSING'
        AND lease_until <= #{now}
        AND attempt_count >= #{maximumAttempts}
  )

UPDATE qa_answer_cancel_task
SET task_status = 'FAILED',
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = #{errorCode},
    updated_at = #{now}
WHERE answer_id = #{answerId}
  AND task_status = 'PROCESSING'
  AND lease_until <= #{now}
  AND attempt_count >= #{maximumAttempts}

UPDATE qa_answer_cancel_task
SET task_status = 'PROCESSING',
    lease_owner = #{workerId},
    lease_until = #{leaseUntil},
    attempt_count = attempt_count + 1,
    updated_at = #{now}
WHERE answer_id = #{answerId}
  AND (
      (task_status = 'PENDING'
          AND next_attempt_at <= #{now}
          AND attempt_count < #{maximumAttempts})
      OR (task_status = 'PROCESSING'
          AND lease_until <= #{now}
          AND attempt_count < #{maximumAttempts})
  )

UPDATE qa_answer
SET status = 'CANCELLED',
    cancelled_at = #{cancelledAt},
    completed_at = #{cancelledAt},
    cancel_error_code = NULL
WHERE public_id = #{answerId}
  AND status = 'CANCEL_REQUESTED'
  AND EXISTS (
      SELECT 1 FROM qa_answer_cancel_task
      WHERE answer_id = #{answerId}
        AND task_status = 'PROCESSING'
        AND lease_owner = #{workerId}
  )

UPDATE qa_answer_cancel_task
SET task_status = 'COMPLETED',
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = NULL,
    updated_at = #{now}
WHERE answer_id = #{answerId}
  AND task_status = 'PROCESSING'
  AND lease_owner = #{workerId}

UPDATE qa_answer_cancel_task
SET task_status = 'PENDING',
    next_attempt_at = #{nextAttemptAt},
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = #{errorCode},
    updated_at = #{nextAttemptAt}
WHERE answer_id = #{answerId}
  AND task_status = 'PROCESSING'
  AND lease_owner = #{workerId}

UPDATE qa_answer
SET cancel_error_code = #{errorCode}
WHERE public_id = #{answerId}
  AND status = 'CANCEL_REQUESTED'

UPDATE qa_answer
SET status = 'CANCEL_FAILED',
    cancel_error_code = #{errorCode},
    completed_at = #{failedAt}
WHERE public_id = #{answerId}
  AND status = 'CANCEL_REQUESTED'
  AND EXISTS (
      SELECT 1 FROM qa_answer_cancel_task
      WHERE answer_id = #{answerId}
        AND task_status = 'PROCESSING'
        AND lease_owner = #{workerId}
  )

UPDATE qa_answer_cancel_task
SET task_status = 'FAILED',
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = #{errorCode},
    updated_at = #{failedAt}
WHERE answer_id = #{answerId}
  AND task_status = 'PROCESSING'
  AND lease_owner = #{workerId}
